import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../..', import.meta.url));
const skillDir = join(root, 'skills', 'twring');
const output = join(root, 'apps', 'connector', 'src', 'skill-files.ts');
const hermesDir = join(root, 'integrations', 'hermes', 'skills', 'twring');

export const HERMES_HEADER =
  '<!-- Generated from skills/twring by apps/connector/scripts/gen-skill.mjs. Do not edit; run `pnpm --filter @twring/connector gen:skill`. -->';

const OPEN = /^<!-- (only|not):([a-z][a-z0-9-]*) -->$/;
const CLOSE = /^<!-- \/(only|not) -->$/;
const ANY_MARKER = /<!-- \/?(only|not)(:|\s)/;

/** Keeps the lines meant for `agent` and drops every marker line. */
export function renderFor(text, agent, name = 'text') {
  const out = [];
  let block;
  const lines = text.replace(/\r/g, '').split('\n');
  lines.forEach((line, index) => {
    const at = `${name}:${index + 1}`;
    const open = OPEN.exec(line);
    const close = CLOSE.exec(line);
    if (open !== null) {
      if (block !== undefined) throw new Error(`${at}: nested agent marker`);
      block = { kind: open[1], target: open[2], line: index + 1 };
      return;
    }
    if (close !== null) {
      if (block === undefined || block.kind !== close[1])
        throw new Error(`${at}: unmatched marker ${line}`);
      block = undefined;
      return;
    }
    if (ANY_MARKER.test(line)) throw new Error(`${at}: an agent marker must be alone on its line`);
    if (block !== undefined) {
      const forAgent = block.target === agent;
      if (block.kind === 'only' ? !forAgent : forAgent) return;
    }
    out.push(line);
  });
  if (block !== undefined) throw new Error(`${name}:${block.line}: agent marker is never closed`);
  return out.join('\n');
}

/** The "generated" note: after SKILL.md's frontmatter (it must start with ---), else first. */
export function withHermesHeader(path, content) {
  if (path === 'SKILL.md') {
    const end = content.indexOf('\n---\n', 3);
    if (!content.startsWith('---\n') || end < 0) throw new Error('SKILL.md has no frontmatter');
    const cut = end + '\n---\n'.length;
    return `${content.slice(0, cut)}${HERMES_HEADER}\n${content.slice(cut)}`;
  }
  return `${HERMES_HEADER}\n\n${content}`;
}

async function filesUnder(dir) {
  const paths = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) paths.push(...(await filesUnder(path)));
    else if (entry.isFile()) paths.push(path);
  }
  return paths;
}

async function readOrUndefined(path) {
  return readFile(path, 'utf8').catch((error) => {
    if (error.code === 'ENOENT') return undefined;
    throw error;
  });
}

export async function buildSkill() {
  const paths = (await filesUnder(skillDir)).sort();
  const sources = await Promise.all(
    paths.map(async (path) => ({
      path: relative(skillDir, path).split(sep).join('/'),
      content: await readFile(path, 'utf8'),
    })),
  );
  return {
    generic: sources.map((file) => ({
      path: file.path,
      content: renderFor(file.content, 'generic', file.path),
    })),
    hermes: sources.map((file) => ({
      path: file.path,
      content: withHermesHeader(file.path, renderFor(file.content, 'hermes', file.path)),
    })),
  };
}

function tsModule(generic, hermes) {
  const list = (files) =>
    files
      .map(
        (file) =>
          `  { path: ${JSON.stringify(file.path)}, content: ${JSON.stringify(file.content)} },`,
      )
      .join('\n');
  return `// Generated by scripts/gen-skill.mjs from skills/twring. Do not edit; run \`pnpm --filter @twring/connector gen:skill\`.\nexport const SKILL_NAME = 'twring';\nexport const SKILL_FILES: readonly { path: string; content: string }[] = [\n${list(generic)}\n];\nexport const HERMES_SKILL_FILES: readonly { path: string; content: string }[] = [\n${list(hermes)}\n];\n`;
}

/** Writes both builds; with `check`, writes nothing. Returns what is (or was) out of date. */
export async function generateSkill({ check = false } = {}) {
  const { generic, hermes } = await buildSkill();
  const wanted = new Map([[output, tsModule(generic, hermes)]]);
  for (const file of hermes) wanted.set(join(hermesDir, ...file.path.split('/')), file.content);
  const stale = [];
  for (const [path, content] of wanted) {
    const current = await readOrUndefined(path);
    // Git may check markdown out with CRLF on Windows; only the text matters.
    if (current !== undefined && current.replace(/\r/g, '') === content) continue;
    stale.push(path);
    if (!check) {
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, content);
    }
  }
  const existing = await filesUnder(hermesDir).catch((error) => {
    if (error.code === 'ENOENT') return [];
    throw error;
  });
  for (const path of existing) {
    if (wanted.has(path)) continue;
    stale.push(path);
    if (!check) await rm(path);
  }
  return stale.map((path) => relative(root, path).split(sep).join('/'));
}

/** The generic pack as a `twring/` folder, for scripts/package-skill.sh. */
export async function writeGenericPack(dir) {
  const { generic } = await buildSkill();
  for (const file of generic) {
    const destination = join(dir, 'twring', ...file.path.split('/'));
    await mkdir(dirname(destination), { recursive: true });
    await writeFile(destination, file.content);
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const args = process.argv.slice(2);
  if (args[0] === '--out-generic' && args[1] !== undefined) {
    await writeGenericPack(args[1]);
  } else {
    const check = args.includes('--check');
    const stale = await generateSkill({ check });
    if (check && stale.length > 0) {
      console.error(
        `The generated Twring skill is out of date: ${stale.join(', ')}. Run \`pnpm --filter @twring/connector gen:skill\` and commit the result.`,
      );
      process.exitCode = 1;
    }
  }
}
